def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    color_by_size = {
        (3, 3): 8,
        (5, 5): 4,
        (7, 7): 3,
    }

    rectangles = []
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    if not all(grid[r0][c] == 2 and grid[r1][c] == 2
                               for c in range(c0, c1 + 1)):
                        continue
                    if not all(grid[r][c0] == 2 and grid[r][c1] == 2
                               for r in range(r0, r1 + 1)):
                        continue
                    ih, iw = r1 - r0 - 1, c1 - c0 - 1
                    color = color_by_size.get((ih, iw))
                    if color is None:
                        continue
                    if any(grid[r][c] == 2
                           for r in range(r0 + 1, r1)
                           for c in range(c0 + 1, c1)):
                        rectangles.append((r0, r1, c0, c1, color))

    for r0, r1, c0, c1, color in rectangles:
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if out[r][c] == 0:
                    out[r][c] = color
    return out
